import * as T from '../vendor/three.module.js';
import {SKY_MAP as MAP} from './sky-map-data.js';
export const SKY_SCALE=10,SKY_LEVEL=228;
// Satellite clusters are separated where the reference shows narrow sky channels.
const SATELLITES=[[-174.5,31.5,3.4,4.5],[-158.5,43,3.1,4.2],[-155,48,3.7,4.5],[-165.5,55,3.3,4.2],[-136,23.5,4.6,6],[-152,85,5.7,7.6],[-155,73,3.4,4.5],[-189.5,59,3.1,4.2],[-150,122,3.5,5],[-144.5,114,3,4.1],[-141,109,2.9,4],[-117,62,3.1,4.1]];
export function referenceCell(x,z){const a=Math.floor(x/10-MAP.originX),b=Math.floor((z/10-MAP.originZ)/MAP.cellZ);if(a<0||b<0||a>=MAP.width||b>=MAP.height)return 0;const raw=Number(MAP.rows[b][a]);const distances=SATELLITES.map(([cx,cz,rx,rz])=>((x/10-cx)/rx)**2+((z/10-cz)/rz)**2);if(distances.some(d=>d<.65))return raw===2?2:1;if(distances.some(d=>d<2.2))return 0;return raw;}
export function referenceHeight(x,z){const kind=referenceCell(x,z);if(!kind)return null;if(kind===2)return SKY_LEVEL-1.5;const a=x/10,b=z/10;return SKY_LEVEL+38*Math.exp(-(((a+123)/15)**2+((b-87)/27)**2))+30*Math.exp(-(((a+151)/9)**2+((b-120)/12)**2));}
export const OVERWORLD_SHRINES=[{id:'weave',name:'Joining Shrine',x:-1590,z:220,entry:{x:-145,y:76,z:78}},{id:'bind',name:'Equipment Shrine',x:-1780,z:900,entry:{x:-173,y:76,z:94}},{id:'rise',name:'Ascent Shrine',x:-1370,z:830,entry:{x:-115,y:85,z:85}},{id:'echo',name:'Rewind Shrine',x:-1510,z:1120,entry:{x:-150,y:104,z:119}}];
export class SkyOverworld{
 constructor(g){this.g=g;this.group=new T.Group();g.scene.add(this.group);this.group.visible=false;this.shrines=OVERWORLD_SHRINES.map(s=>({...s}));this.build();}
 heightAt(x,z){const gx=x/10-MAP.originX,gz=(z/10-MAP.originZ)/MAP.cellZ,ix=Math.floor(gx),iz=Math.floor(gz);if(ix<0||iz<0||ix>=MAP.width-1||iz>=MAP.height-1)return null;const ax=(MAP.originX+ix)*10,az=(MAP.originZ+iz*MAP.cellZ)*10,pts=[[ax,az],[ax+10,az],[ax+10,az+14.8],[ax,az+14.8]],h=pts.map(p=>referenceHeight(...p));if(h.some(v=>v===null))return null;const u=gx-ix,v=gz-iz;return u>=v?h[0]+u*(h[1]-h[0])+v*(h[2]-h[1]):h[0]+v*(h[3]-h[0])+u*(h[2]-h[3]);}
 landing(x,z){let best=null;for(let r=0;r<=100&&!best;r+=5)for(let a=0;a<(r?16:1);a++){const px=x+Math.cos(a*Math.PI/8)*r,pz=z+Math.sin(a*Math.PI/8)*r,h=this.heightAt(px,pz);if(h!==null&&referenceCell(px,pz)===1){best={x:px,y:h+.025,z:pz};break;}}if(!best)throw Error('No safe sky landing near this landmark.');return best;}
 build(){const g=this.g,w=g.world,positions=[],colors=[],waters=[];const tri=(a,b,c,col)=>{positions.push(...a,...b,...c);for(let i=0;i<3;i++)colors.push(col.r,col.g,col.b);};let cells=0;
  for(let z=0;z<MAP.height-1;z++)for(let x=0;x<MAP.width-1;x++){const ax=(MAP.originX+x)*10,az=(MAP.originZ+z*MAP.cellZ)*10,pts=[[ax,az],[ax+10,az],[ax+10,az+14.8],[ax,az+14.8]],hs=pts.map(p=>referenceHeight(...p));if(hs.some(h=>h===null))continue;cells++;const p=pts.map(([x,z],i)=>[x,hs[i],z]),snow=hs[0]>245,c=new T.Color(snow?0xd8dfcf:0xb5bb83).multiplyScalar(.95+((x*17+z*13)%7)*.01);tri(p[0],p[2],p[1],c);tri(p[0],p[3],p[2],c);
   if(pts.every(p=>referenceCell(...p)===2)){for(const i of [0,2,1,0,3,2])waters.push(p[i][0],SKY_LEVEL,p[i][2]);}
   for(let i=0;i<4;i++){const k=(i+1)%4,dx=pts[k][0]-pts[i][0],dz=pts[k][1]-pts[i][1],mx=(pts[i][0]+pts[k][0])/2+dz*.55,mz=(pts[i][1]+pts[k][1])/2-dx*.55;if(referenceHeight(mx,mz)!==null)continue;const a=p[i],b=p[k],c=[b[0],b[1]-65,b[2]],d=[a[0],a[1]-65,a[2]],rock=new T.Color(0x6f8a7c);tri(a,b,c,rock);tri(a,c,d,rock);}
  }
  const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const terrain=new T.Mesh(geo,new T.MeshStandardMaterial({vertexColors:true,roughness:.95,side:T.DoubleSide}));terrain.castShadow=terrain.receiveShadow=true;this.group.add(terrain);this.terrain=terrain;this.cellCount=cells;
  const waterGeo=new T.BufferGeometry();waterGeo.setAttribute('position',new T.Float32BufferAttribute(waters,3));waterGeo.computeVertexNormals();this.group.add(new T.Mesh(waterGeo,new T.MeshStandardMaterial({color:0x76b9b8,roughness:.24,metalness:.2,side:T.DoubleSide})));
  // Instanced vegetation keeps hundreds of separate trees within a small draw budget.
  let seed=81041;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},trees=[];for(let i=0;i<1800&&trees.length<260;i++){const x=-1930+random()*850,z=-40+random()*1310,h=this.heightAt(x,z);if(h===null||h>244||referenceCell(x,z)!==1||this.shrines.some(s=>Math.hypot(s.x-x,s.z-z)<35))continue;trees.push({x,z,h});}
  const trunks=new T.InstancedMesh(w.geos.cylinder,w.material(0x66705b),trees.length),leaves=new T.InstancedMesh(w.geos.sphere,w.material(0xbec279),trees.length*3),dummy=new T.Object3D();trees.forEach((p,i)=>{dummy.position.set(p.x,p.h+4,p.z);dummy.scale.set(.65,8,.7);dummy.rotation.set(0,0,0);dummy.updateMatrix();trunks.setMatrixAt(i,dummy.matrix);for(let n=0;n<3;n++){dummy.position.set(p.x+Math.cos(n*2.4)*3,p.h+9+n,p.z+Math.sin(n*2.4)*3);dummy.scale.set(5,3.5,4.8);dummy.updateMatrix();leaves.setMatrixAt(i*3+n,dummy.matrix);}});trunks.castShadow=leaves.castShadow=true;this.group.add(trunks,leaves);
  for(const s of this.shrines){const p=this.landing(s.x,s.z);Object.assign(s,p);this.platform('overworld-shrine-'+s.id,p,12);for(const dx of [-4,4])w.mesh('cylinder',0xd5d7b8,this.group,p.x+dx,p.y+5,p.z,.55,10,.55);const arch=new T.Mesh(new T.TorusGeometry(4,.6,8,28,Math.PI),w.material(0xcfd8bb));arch.position.set(p.x,p.y+10,p.z);this.group.add(arch);w.mesh('sphere',0x88e5c3,this.group,p.x,p.y+7,p.z,.65,1,.65,.7);w.interactables.push({id:'overworld-'+s.id,type:'journey-enter',trial:s.id,...p,r:5,label:'Enter '+s.name});}
  this.temple=this.landing(-1450,35);this.platform('overworld-temple',this.temple,65);for(const dx of [-23,-15,15,23]){w.mesh('box',0x879d83,this.group,this.temple.x+dx,this.temple.y+2,this.temple.z,5,4,6);w.mesh('box',0xe1dfc5,this.group,this.temple.x+dx,this.temple.y+25,this.temple.z,3,44,4);}const arch=new T.Mesh(new T.TorusGeometry(15,1.4,9,40,Math.PI),w.material(0xe0dfc5));arch.position.set(this.temple.x,this.temple.y+45,this.temple.z);this.group.add(arch);w.mesh('box',0xb9c8ae,this.group,this.temple.x,this.temple.y+65,this.temple.z,60,2.5,10);w.mesh('cone',0x769583,this.group,this.temple.x,this.temple.y+76,this.temple.z,10,20,10);w.interactables.push({id:'overworld-temple',type:'journey-overworld-temple',...this.temple,r:7,label:'Temple of Time · open the descent'});
  this.spawn=this.landing(-1510,1190);this.platform('overworld-awakening',this.spawn,20);w.interactables.push({id:'overworld-guide',type:'journey-overworld-guide',x:this.spawn.x+3,y:this.spawn.y,z:this.spawn.z-3,r:5,label:'Read the keeper’s island chart'});
  this.satellites=[{id:'windbreak-garden',name:'Windbreak Garden',x:-1895,z:590,reward:{fiber:4,broth:1}},{id:'mineral-shelf',name:'Mineral Shelf',x:-1745,z:315,reward:{glass:2,copper:3}},{id:'survey-perch',name:'Surveyor’s Perch',x:-1170,z:620,reward:{fiber:3,copper:2}}];
  for(const site of this.satellites){const p=this.landing(site.x,site.z);Object.assign(site,p);this.platform('satellite-'+site.id,p,12);w.mesh('box',0x92794e,this.group,p.x,p.y+.5,p.z,1.8,1,1.2);w.mesh('box',0xd8bf81,this.group,p.x,p.y+1.05,p.z,1.9,.15,1.3);for(const dx of [-3,3])w.mesh('sphere',0x8a9e79,this.group,p.x+dx,p.y+.5,p.z+2,1.2,.8,1.4);w.interactables.push({id:site.id,type:'journey-satellite',...p,r:3,label:'Explore '+site.name,site});}
  this.stops=[...this.satellites.map(s=>({id:s.id,name:s.name,x:s.x,y:s.y,z:s.z})),{id:'awakening',name:'Awakening landing',...this.spawn},...this.shrines.map(s=>({id:s.id,name:s.name,x:s.x,y:s.y,z:s.z})),{id:'temple',name:'Temple of Time',...this.temple}];
  for(const stop of this.stops){const dock={x:stop.x+12,y:stop.y,z:stop.z};this.platform('ferry-'+stop.id,dock,10);w.mesh('box',0xa68a5c,this.group,stop.x+6,stop.y-.07,stop.z,14,.2,3);w.solids.push({id:'ferry-gangway-'+stop.id,x:stop.x+6,z:stop.z,w:14,d:3,top:stop.y+.03,bottom:stop.y-.17});w.mesh('cylinder',0x84b4a0,this.group,dock.x,dock.y+2,dock.z,.3,4,.3);w.mesh('ring',0xa9dac0,this.group,dock.x,dock.y+4,dock.z,1.2,1.2,1.2,.3);w.interactables.push({id:'wind-ferry-'+stop.id,type:'journey-ferry',stop:stop.id,...dock,r:4,label:'Board the island wind ferry'});stop.dock=dock;}
  this.mapRows=MAP.rows.map((row,z)=>[...row].map((_,x)=>String(referenceCell((MAP.originX+x)*10,(MAP.originZ+z*1.48)*10))).join(''));this.mapRects=this.mapRows.map((row,z)=>[...row].map((c,x)=>c==='0'?'':`<rect x="${x}" y="${z}" width="1.05" height="1.05" fill="${c==='2'?'#7aaca8':'#c8c498'}"/>`).join('')).join('');
 }
 platform(id,p,size){this.g.world.mesh('cylinder',0xc4c6ab,this.group,p.x,p.y-.3,p.z,size/2,.6,size/2);this.g.world.solids.push({id,x:p.x,z:p.z,w:size*.7,d:size*.7,top:p.y,bottom:p.y-.6});}
 mapSVG(p){const x=p.x/10-MAP.originX,z=(p.z/10-MAP.originZ)/1.48;return `<svg class="worldmap" viewBox="0 0 88 99" role="img" aria-label="Reference-derived sky archipelago map"><rect width="88" height="99" fill="#a7c2c3"/>${this.mapRects}${this.shrines.map(s=>`<path d="M${s.x/10-MAP.originX} ${(s.z/10-MAP.originZ)/1.48-1.5}l1.5 1.5-1.5 1.5-1.5-1.5Z" fill="#348caa"/>`).join('')}<circle cx="${x}" cy="${z}" r="1.1" fill="#704526"/></svg>`;}
 drawMini(ctx,p){ctx.clearRect(0,0,264,264);ctx.fillStyle='#a7c2c3';ctx.fillRect(0,0,264,264);for(let z=0;z<99;z++)for(let x=0;x<88;x++){const c=this.mapRows[z][x];if(c==='0')continue;ctx.fillStyle=c==='2'?'#7aaca8':'#c8c498';ctx.fillRect(x*3,z*2.65,3.1,2.75);}ctx.fillStyle='#704526';ctx.beginPath();ctx.arc((p.x/10-MAP.originX)*3,(p.z/10-MAP.originZ)/1.48*2.65,3,0,7);ctx.fill();}
}
